remote_cmd="${@: -1}"
case "$remote_cmd" in
  *loadavg*) echo "2.00" ;;
  *nproc*)   echo "4" ;;
  *) exit 1 ;;
esac
EOF
chmod +x "$SANDBOX/bin/ssh"
export PATH="$SANDBOX/bin:$PATH"

