  echo "$?"
}

input.new_string:
mkdir -p "$SANDBOX/bin"
ln -s "$(command -v gawk)" "$SANDBOX/bin/awk"
cat > "$SANDBOX/bin/ssh" <<'EOF'
#!/bin/bash
# Fake ssh: fakes load/cpus per host so tests can control which host "wins".
#   fake-host-1: load=2.00 cpus=4 (normalized 0.50)
#   busy-host:   load=8.00 cpus=2 (normalized 4.00)
#   idle-host:   load=2.00 cpus=4 (normalized 0.50)
host=""
for arg in "$@"; do
  case "$arg" in
    deploy@*) host="${arg#deploy@}" ;;
  esac
done
remote_cmd="${@: -1}"
case "$host" in
  fake-host-1|idle-host)
    case "$remote_cmd" in
      *loadavg*) echo "2.00" ;;
      *nproc*)   echo "4" ;;
      *) exit 1 ;;
    esac
    ;;
  busy-host)
    case "$remote_cmd" in
      *loadavg*) echo "8.00" ;;
      *nproc*)   echo "2" ;;
      *) exit 1 ;;
    esac
    ;;
  *) exit 1 ;;
esac
EOF
chmod +x "$SANDBOX/bin/ssh"
export PATH="$SANDBOX/bin:$PATH"

run_variant() {
  local script_path="$1"
  local hosts="$2"
  bash "$script_path" "$hosts" >"$SANDBOX/stdout" 2>"$SANDBOX/stderr"
  echo "$?"
}

